<template><BaseModal :open="open" :title="title" :description="description" @close="$emit('cancel')"><div v-if="kind==='privileged'" class="vs-confirm__notice" role="note"><strong>Hành động đặc quyền</strong><p>Hệ thống có thể yêu cầu xác thực tăng cường trước khi thực thi.</p></div><slot/><template #footer><BaseButton variant="secondary" :disabled="loading" @click="$emit('cancel')">{{cancelLabel}}</BaseButton><BaseButton :variant="kind==='destructive'?'danger':'primary'" :loading="loading" @click="$emit('confirm')">{{confirmLabel}}</BaseButton></template></BaseModal></template>
<script setup>import BaseButton from './BaseButton.vue';import BaseModal from './BaseModal.vue';defineProps({open:Boolean,title:{type:String,required:true},description:{type:String,default:''},kind:{type:String,default:'normal'},confirmLabel:{type:String,default:'Xác nhận'},cancelLabel:{type:String,default:'Hủy'},loading:Boolean});defineEmits(['confirm','cancel'])</script>
<style scoped>.vs-confirm__notice{padding:var(--space-3);border:1px solid var(--status-warning-border);border-radius:var(--radius-control);background:var(--status-warning-bg);color:var(--status-warning-text)}.vs-confirm__notice p{margin-top:var(--space-1);font-size:var(--type-body-size);line-height:var(--type-body-line)}</style>
